inline std::optional<flight::String> validate_radio_groups(flight::Array<flight::Ref<MenuItemTemplate>> items) {
  double checked_in_run = 0.0;
  for (auto item : items) {
    if ((item->type != flight::String("radio"))) {
      (checked_in_run = 0.0);
      continue;
    }
    if ((item->checked == true)) {
      checked_in_run++;
    }
    if ((checked_in_run > 1.0)) {
      return std::optional<flight::String>{flight::String("radio group has ") + flight::to_string(checked_in_run) + flight::String(" checked items (a radio group may have at most one)")};
    }
  }
  return std::nullopt;
}


